<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserProfile\Domain\ValueObject\Accessor\UserProfileWebsiteUrlAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserProfileWebsiteUrlAccessor trait.
 *
 * Covers null default, string/VO assignment via withWebsiteUrl,
 * getWebsiteUrl/websiteUrl accessors, and isWebsiteUrlChanged with/without original.
 */
class UserProfileWebsiteUrlAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withWebsiteUrl creates a new instance with the WebsiteUrl set
     * from a string value, and getWebsiteUrl returns the primitive string.
     */
    public function testWithWebsiteUrlFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserProfileWebsiteUrlAccessorUnitTest();

        // Act
        $result = $holder->withWebsiteUrl('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getWebsiteUrl());
    }
    /**
     * Asserts that withwebsiteUrl has access to the value object
     * from a string value, and getWebsiteUrl returns the primitive string.
     */
    public function testWithWebsiteUrlFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserProfileWebsiteUrlAccessorUnitTest();

        // Act
        $result = $holder->withWebsiteUrl('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->websiteUrl()->value());
    }
    public function testChangedWebsiteUrl(): void
    {
        // Arrange
        $holder = new ImplWithUserProfileWebsiteUrlAccessorUnitTest();
        $original = $holder->withWebsiteUrl('one');
        $same = $holder->withWebsiteUrl('one');
        $modified = $holder->withWebsiteUrl('other');

        // Act
        $unchanged = $holder->isWebsiteUrlChanged();
        $withSame = $original->isWebsiteUrlChanged($same);
        $withDiferent = $original->isWebsiteUrlChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserProfileWebsiteUrlAccessorUnitTest
{
    use UserProfileWebsiteUrlAccessor;
}
